using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using TxTools.ExportByColor;
class RoundCylinderOpenRimRegression {
 static void Check(bool x,string message){if(!x)throw new Exception(message);}
 static int Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string p=Path.Combine(args[0],new AssemblyName(e.Name).Name+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{Run();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Run(){foreach(bool outer in new[]{false,true})foreach(bool rotated in new[]{false,true})Test(outer,rotated);TestCappedEnd();TestSplitCap(false);TestSplitCap(true);foreach(string bad in new[]{"longitudinal-gap","nonplanar-rim","cone","ellipse","hexagon","overlap"})Reject(bad);}
 static void TestSplitCap(bool duplicate){const int n=16;var v=new List<float[]>();var f=new List<CgrWriter.Face>();Mesh(n,false,v,f);for(int i=0;i<n;i++){double a=2*Math.PI*i/n;v.Add(new[]{(float)(12*Math.Cos(a)),(float)(12*Math.Sin(a)),0f});}for(int i=0;i<n;i++){int j=(i+1)%n;foreach(var t in new[]{new[]{i,2*n+j,2*n+i},new[]{i,j,2*n+j}})f.Add(new CgrWriter.Face{Idx=t,Surface=20,R=190,G=71,B=32,Opacity=255});}if(duplicate)foreach(var original in f.Skip(2*n).ToArray()){var copy=original;copy.Surface=21;f.Add(copy);}var h=RoundHoleReconstruction.Find(v,f,new RoundHoleReconstruction.Options{IncludeExternalCylinders=true,IncludeTransitionRims=true,IncludeOpenCylinderEnds=true});Check(h.Count==1&&h[0].PairedRims&&h[0].OpenRimA&&h[0].OpenRimB,"Split Shape shell was not fitted independently");var r=RoundHoleCgrMesh.Replace(v,f,h,Console.WriteLine);Check(r.Cylinders.Count==1&&r.RemovedWallTriangles==2*n&&r.ReplacedCapTriangles==(duplicate?0:2*n),"Split cap match was omitted or ambiguous cap was arbitrarily chosen");Check(r.Faces.Where(x=>x.Surface==20).All(x=>x.R==190&&x.G==71&&x.B==32&&x.Opacity==255),"Split cap color changed");if(!duplicate){var edges=new Dictionary<string,int>();foreach(var face in r.Faces)for(int k=0;k<3;k++){string a=Point(r.Vertices[face.Idx[k]]),b=Point(r.Vertices[face.Idx[(k+1)%3]]),key=string.CompareOrdinal(a,b)<0?a+"|"+b:b+"|"+a;int count;edges.TryGetValue(key,out count);edges[key]=count+1;}Check(edges.Values.All(x=>x==1||x==2)&&edges.Values.Count(x=>x==1)==r.AddedWallTriangles/2+n,"Split cap join left a crack");}Console.WriteLine("PASS split Shape cap duplicate="+duplicate+"; exact full rim, cap color, ambiguous joins retained");}
 static void TestCappedEnd(){const int n=16;var v=new List<float[]>();var f=new List<CgrWriter.Face>();Mesh(n,false,v,f);for(int i=0;i<n;i++){double a=2*Math.PI*i/n;v.Add(new[]{(float)(12*Math.Cos(a)),(float)(12*Math.Sin(a)),0f});}for(int i=0;i<n;i++){int j=(i+1)%n;foreach(var t in new[]{new[]{i,2*n+j,2*n+i},new[]{i,j,2*n+j}})f.Add(new CgrWriter.Face{Idx=t,Surface=19,R=23,G=91,B=187,Opacity=128});}var h=RoundHoleReconstruction.Find(v,f,new RoundHoleReconstruction.Options{IncludeExternalCylinders=true,IncludeTransitionRims=true,IncludeOpenCylinderEnds=true});Check(h.Count==1&&h[0].PairedRims&&h[0].OpenRimA!=h[0].OpenRimB,"One joined/one open cylinder end was lost");var r=RoundHoleCgrMesh.Replace(v,f,h);Check(r.Cylinders.Count==1&&r.RemovedWallTriangles==2*n&&r.ReplacedCapTriangles==2*n,"Joined annular cap was not replaced atomically");var edgeCounts=new Dictionary<string,int>();foreach(var face in r.Faces)for(int k=0;k<3;k++){string a=Point(r.Vertices[face.Idx[k]]),b=Point(r.Vertices[face.Idx[(k+1)%3]]),key=string.CompareOrdinal(a,b)<0?a+"|"+b:b+"|"+a;int count;edgeCounts.TryGetValue(key,out count);edgeCounts[key]=count+1;}Check(edgeCounts.Values.All(x=>x==1||x==2)&&edgeCounts.Values.Count(x=>x==1)==r.AddedWallTriangles/2+n,"Joined end has cracks or the open end was capped");Console.WriteLine("PASS one source open end and one joined annular cap; atomic replacement and original open boundaries");}
 static void Mesh(int n,bool outer,List<float[]> v,List<CgrWriter.Face> f){for(int ring=0;ring<2;ring++)for(int i=0;i<n;i++){double a=2*Math.PI*i/n;v.Add(new[]{(float)(5*Math.Cos(a)),(float)(5*Math.Sin(a)),ring*17f});}for(int i=0;i<n;i++){int j=(i+1)%n;foreach(var t in new[]{new[]{i,j,n+j},new[]{i,n+j,n+i}}){if(!outer){int swap=t[1];t[1]=t[2];t[2]=swap;}f.Add(new CgrWriter.Face{Idx=t,Surface=19,R=23,G=91,B=187,Opacity=128});}}}
 static string Point(float[] p){return string.Join(",",p.Select(x=>x.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));}
 static void Test(bool outer,bool rotated){var v=new List<float[]>();var f=new List<CgrWriter.Face>();Mesh(16,outer,v,f);if(rotated)foreach(var p in v){double x=p[0],y=p[1],z=p[2];p[0]=(float)(1000+.8*x+.36*y+.48*z);p[1]=(float)(2000+.6*x-.48*y-.64*z);p[2]=(float)(3000+.8*y-.6*z);}var original=v.Select(p=>(float[])p.Clone()).ToList();var triangles=f.Select(p=>(int[])p.Idx.Clone()).ToList();Check(RoundHoleReconstruction.Find(v,f,new RoundHoleReconstruction.Options{IncludeExternalCylinders=true}).Count==0,"Default analysis accepted an unjoined shell");var h=RoundHoleReconstruction.Find(v,f,new RoundHoleReconstruction.Options{IncludeExternalCylinders=true,IncludeTransitionRims=true,IncludeOpenCylinderEnds=true});Check(h.Count==1&&h[0].PairedRims&&h[0].OpenRimA&&h[0].OpenRimB,"Complete source open rings were not paired");var r=RoundHoleCgrMesh.Replace(v,f,h);Check(r.Cylinders.Count==1&&r.RemovedWallTriangles==f.Count&&r.ReplacedCapTriangles==0,"Open cylinder was not replaced without inventing caps");var c=r.Cylinders.Values.Single();Check(c.ExternalCylinder==outer&&Math.Abs(c.Radius-5)<.001&&Math.Abs(c.Depth-17)<.001,"Cylinder dimensions changed");Check(r.Faces.All(x=>x.R==23&&x.G==91&&x.B==187&&x.Opacity==128),"RGBA changed");var edgeCounts=new Dictionary<string,int>();foreach(var face in r.Faces)for(int k=0;k<3;k++){string a=Point(r.Vertices[face.Idx[k]]),b=Point(r.Vertices[face.Idx[(k+1)%3]]),key=string.CompareOrdinal(a,b)<0?a+"|"+b:b+"|"+a;int n;edgeCounts.TryGetValue(key,out n);edgeCounts[key]=n+1;}Check(edgeCounts.Values.All(n=>n==1||n==2)&&edgeCounts.Values.Count(n=>n==1)==r.AddedWallTriangles,"Unexpected cracks or invented closure");Check(v.Select((p,i)=>p.SequenceEqual(original[i])).All(x=>x)&&f.Select((p,i)=>p.Idx.SequenceEqual(triangles[i])).All(x=>x),"Input mutated");Console.WriteLine("PASS complete source open "+(outer?"outer":"inner")+" rotated="+rotated+"; dimensions, RGBA, two open boundaries, no caps");}
 static void Reject(string kind){var v=new List<float[]>();var f=new List<CgrWriter.Face>();int n=kind=="hexagon"?6:16;Mesh(n,false,v,f);if(kind=="longitudinal-gap")f.RemoveRange(0,2);if(kind=="nonplanar-rim")v[0][2]+=1;if(kind=="cone")for(int i=n;i<2*n;i++){v[i][0]*=1.2f;v[i][1]*=1.2f;}if(kind=="ellipse")foreach(var p in v)p[1]*=1.2f;if(kind=="overlap")f.AddRange(f.ToArray());var h=RoundHoleReconstruction.Find(v,f,new RoundHoleReconstruction.Options{IncludeExternalCylinders=true,IncludeTransitionRims=true,IncludeOpenCylinderEnds=true});Check(!h.Any(x=>x.PairedRims),"Unsupported source shell accepted: "+kind);Console.WriteLine("PASS rejected "+kind);}
}
